/* `cls` names the patch class `full`: its full name, or a bare name for any namespace (hw.txt genpatch) */
bool Is(const char* cls, const char* full) {
    if (!std::strcmp(cls, full)) return true;
    if (std::strchr(cls, '.')) return false;
    size_t n = std::strlen(cls), k = std::strlen(full);
    return k > n && full[k - n - 1] == '.' && !std::strcmp(full + k - n, cls);
}
/* `name` is one of the comma-separated names in `list` */
bool Listed(const char* list, const char* name) {
    size_t n = std::strlen(name);
    for (const char* p = list; p && *p;) {
        const char* e = std::strchr(p, ',');
        size_t k = e ? (size_t)(e - p) : std::strlen(p);
        while (k && p[0] == ' ') { p++; k--; }
        while (k && p[k - 1] == ' ') k--;
        if (k == n && !std::strncmp(p, name, n)) return true;
        p = e ? e + 1 : nullptr;
    }
    return false;
}
